        { term: "Biogeochemical Cycles", definition: "The cycling of chemical elements (Carbon, Oxygen, Nitrogen) between living organisms and the physical environment." },
        { term: "Carbon Cycle", definition: "The continuous movement of carbon through the biosphere, atmosphere, oceans, and geosphere (via photosynthesis/respiration)." },
        { term: "Primary Succession", definition: "Succession occurring on newly exposed or formed land devoid of soil (e.g., lava flow or retreated glacier)." },
        { term: "Secondary Succession", definition: "Succession occurring in an area where the existing community has been partially or completely destroyed (e.g., forest fire)." },
        { term: "Biome", definition: "A large geographical area characterized by its vegetation, soil, climate, and wildlife (e.g., Tundra, Desert, Tropical Rainforest)." }
